import { SiteList } from "./components/SiteList";
import { SitePage } from "./components/SitePage";
import { dataUrl } from "./lib";
import { useRoute } from "./router";

// Links to the pages that are still generated by the Python scripts, relative to docs/app/.
const NAV: [label: string, href: string][] = [
  ["Atlas", dataUrl("index.html")],
  ["3D model", dataUrl("3d.html")],
  ["Stories", dataUrl("stories.html")],
  ["Day vs night", dataUrl("daynight.html")],
  ["Meteogram", dataUrl("meteogram.html")],
  ["Site weather", "#/site-weather"],
  ["Map", dataUrl("site-weather/map.html")],
  ["Share today", dataUrl("site-weather/share.html")],
  ["Figures", dataUrl("gallery.html")],
  ["Code", "https://github.com/gavacharles/kampala-heat-atlas"],
];

export function App() {
  const route = useRoute();
  return (
    <main>
      <nav>{NAV.map(([label, href]) => <a key={label} href={href}>{label}</a>)}</nav>
      {route.page === "sites" && <SiteList />}
      {route.page === "site" && <SitePage key={route.slug} slug={route.slug} />}
      {route.page === "missing" && (
        <section>
          <h1>Page not found</h1>
          <p className="lede"><a href="#/site-weather">All sites</a></p>
        </section>
      )}
      <p className="lede" style={{ fontSize: 13 }}>
        Screening guidance from a weather forecast, not an instruction. The contract specification, crane manufacturer's
        limits and site health-and-safety plan take precedence. Forecast and ERA5 data: Open-Meteo (open-meteo.com, CC BY 4.0).
      </p>
      <p className="byline">By Gava Charles · <span>Kampala Heat Atlas</span></p>
    </main>
  );
}
